INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316263-ce305', 'stk-a_dulaziz', 'CE 305', 'info', '{"desc": "أفضل وصف للماده أنها advanced statics\n\nالماده تتكلم بشكل عام عن statically indeterminate structures و طرق حلها\n\nأسئلة الماده طويله شوي و تاخذ وقت\n\nدرستها عن الخثلان\n\nالكونسبت واضح و سهل مقارنه ب 203\n\nأعتبر الماده متوسطه الصعوبه لاكن عيبها طول حل المسائل الي يخلي الشخص صعب يتدرب كثير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-305-structural-analysis-i/120673/2", "user": "A_DULAZIZ", "ts": 1389034387000, "tid": 120673, "pn": 2}}', 1389034387000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492556-ce305', 'stk-_132', 'CE 305', 'info', '{"desc": "نفس الوصف اللي فوق ؛ بالإضافة خذها بعد ce 203 على طول ؛ لان المادة فيه رسم shear force و moment .\nفالمادة فيها ارتباط كبير ب203 فلذلك نزلها بعد 203 على طول (لاتخلي سمستر فاضي بينهم )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-305-structural-analysis-i/120673/3", "user": "_132", "ts": 1526526839000, "tid": 120673, "pn": 3}}', 1526526839000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rami_ali_ce_1990-ce305', 'stk-rami_ali_ce_1990', 'CE 305', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور سعيد درسني CE 305 و كان ال كوأب كوردينيتر\n\nالتحضير : كنت احضر بدري\nطريقة الشرح : للأمانة الشرح غير ممتع ولا كان فيه شغف اني اتعلم اكثر …\nالكويزات : في اولد كويزز تلقى 70% منها جاتك او كذا\nالمياجر: فيه اولد اكزامز ممكن تلقى حول 60 - 55% منها جاتك لكن ماكنت فاهم تمام يعني تخبيص\nالفاينلات : مافتكر\nالقريد النهائي: عطاني افرج\nالصوت: اقل من عادي\nنصيحة: لا تنزل معاه الا اذا انحديت\nإضافات : الدكتور سعيد محترم وخلوق وبشوش اذا اتعاملت معاه بتعرف الشي هذا … مانصح انك تنزل معاه كلاس ابدا لان فيه دكاترة افضل منه بمليون مرة …\n\nبالتسبة للكوأب … للامانة كان مهتم فينا ومحترم معانا تماما في الزيارات الميدانية ومتعاون … الغير ممكن مايوافقني التعليق … القريد كان على ادائك في البرزنتيشن والريبورت و غير كذا خطة الشركة و التقييم الاول والتاني … برا االكلاس محترم ومتعاون … ريحة عطره جميلة مين يوافقني ومين يختلف ؟ 👏 👏 👏 👏", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480804-ce305", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/14", "user": "Rami_Ali_CE_1990", "ts": 1506166850000, "tid": 98562, "pn": 14}}]}', 1506166850000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce305', 'stk-user2967', 'CE 305', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 305 - 101\n\nالتحضير : ببداية كل كلاس … ويسجلك متاخر لو تاخرت\nطريقة الشرح : ع البورد يكتب ويستخدم اوراق مصوره … ومنتاز بالشرح 🙂\nالكويزات : بسيطه\nالمياجر: بسيطه … بس طبعااا المشكلة طبيعة اسئلة الماده حلولها طويله فغصب تغلط … لكن ولله الحمد لو تخطي بالبداية يخصم عليك شي بسيط بس\nالفاينلات : نفس الكلام\nالقريد النهائي: A\nالصوت: واضح إضافات : لاتنسخ الهوم وورك … حاول تنسخ مع تعديل قوي\n\nوموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p777161-ce305", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/7", "user": "user2967", "ts": 1296214232000, "tid": 98578, "pn": 7}}]}', 1296214232000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce305', 'stk-civil_engineer1', 'CE 305', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فصل 111\nce 305\nالتحضير : بداية الكلاس\nطريقة الشرح :يكتب على السبورة … ممتاااز مرة في المادة\nالكويزات : عطانا 4 كويزات … طبعا يكون بيوم تسليم الهوموورك وعلى ماتيريال الهوموورك وبالعادة يكون من امثلة الكتاب وبآخر الفصل قال لنا باخذ احسن 3\nالمياجر: متوسطة لكن كم سؤال فيهم تركات ما تفكهم الا اذا فاهم صح وتصحيحه ممتاز\nالفاينلات :نفس المياجر\nالقريد النهائي: B+\nالصوت:ممتاز\nإضافات :بيتعبك شوية في الكورس بالهومووركات وماعليه من الافرج الفعلي يحط الافرج على اللي هو كان متوقع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974309-ce305", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/11", "user": "civil_engineer1", "ts": 1327613088000, "tid": 98578, "pn": 11}}]}', 1327613088000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_dulaziz-ce305', 'stk-a_dulaziz', 'CE 305', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 305-131\n\nالشرح ما شاء الله 🌹\n\nطريقته نفس 203 ce (تم تقيمها مسبقا)\n\nتصحيح المياجر يشوف الغلط عندك ويبني باقي حلك عليه يعني بس الفقره الغلط ينقصك عليها\n\nسلبيته الوجيده انه شديد بالتعامل (مع اني ما أشوفها سلبيه)\n\nمن وجهة نظري هو الأفضل بالقسم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1317283-ce305", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/19", "user": "A_DULAZIZ", "ts": 1389183313000, "tid": 98578, "pn": 19}}]}', 1389183313000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh1417_2015-ce305', 'stk-saleh1417_2015', 'CE 305', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE305 -181\n\nراح اذكر سلبيات الدكتور وإيجابيته بشكل سريع :-\n\nسلبيات »\n١- يقرأ السلايدات ويأشر عليهم لاتتوقع انه يشرح لك اشياء اساسية في ٢٠١ او ٢٠٣ كيف جت .\n٢- احيانا يعقد بعض الاشياء وهي بسيطة .\n٣- اذا بغيت تراجعه عقب اختبار انت فقط تشوف حلك ومايخطي بالتصحيح دقييق مرة ماشاء الله \" لاتدور الزلة عليه او تدور درجات 🙂 \".\n٤- اختباراته **قاسيه نوعاً **ما وغالب افكارها من النوتات حقاته لاتضيع وقتك مع الهومورك :).\n٥-مو مرن مرة من ناحية الحضور مع شعبة ثانية.\n\nإيجابيات »\n١- الدكتور طيب بشكل عام يجاوب على اسئلة الطلاب بشكل رحب بوسط المحاضرة.\n٢- نوتاته رائعة جدا ويمكن يغنيك عن فتح الكتاب بكبره ! .\n٣ - موجود في المكتب اذا بغيته ويستقبل الطلاب بشكل رحب.\n٤- متفهم ظروف الطلاب بتأجيل (هومورك، كويز، ميجر).\n٥- بشوش ومبتسم دائماً.\n\n-بالنهاية المادة تتطلب منك حل مسائل كثيرة وتدريب ومتعابعة مع الدكتور بشكل دوري “سالفة قبل الميجر بذاكرها وافهمها لا ياحبيبي انسى” .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503768-ce305", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/5", "user": "Saleh1417_2015", "ts": 1545141402000, "tid": 176818, "pn": 5}}]}', 1545141402000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
